-- Engine baseline 0006: views, triggers and row security.
-- GENERATED by `pnpm --filter @engine/db cut` from a structure dump of the source database and
-- supabase-engine/allowlist.json. Do not edit by hand: change the allow-list, or add a new
-- migration after the baseline.

set search_path = public, extensions;

create view public.directory_contributors with (security_invoker=on) as
 SELECT id,
    contributor_slug AS slug,
    full_name AS name,
    contributor_kind AS kind,
    bio,
    website_url,
    instagram_handle,
    facebook_url,
    tiktok_handle,
    youtube_url,
    physical_address,
    physical_latitude,
    physical_longitude,
    avatar_url,
    logo_url,
    gallery_urls,
    created_at,
    contributor_category AS category,
    contributor_no_fixed_location AS no_fixed_location
   FROM profiles
  WHERE role = 'contributor'::text AND contributor_status = 'approved'::text AND contributor_slug IS NOT NULL AND COALESCE(contributor_hidden, false) = false;

